'use client'

import { cn } from '@/lib/utils'
import { AnimatePresence, motion, useDragControls, useMotionValue, useScroll, useTransform } from 'motion/react'
import { useCallback, useEffect, useMemo, useRef, useState, type RefCallback, type RefObject } from 'react'
import { createPortal } from 'react-dom'

export type DocsScrollbarSection = {
  index: number
  title: string
  badge?: string
  element: HTMLElement
}

export type DocsScrollbarProps = {
  containerRef?: RefObject<HTMLElement | null>
  selector?: string
  portal?: boolean
  className?: string
}

export function DocsScrollbar({
  containerRef,
  selector = '[data-page-section]',
  portal = false,
  className,
}: DocsScrollbarProps) {
  const [sections, setSections] = useState<DocsScrollbarSection[]>([])
  const [activeSection, setActiveSection] = useState(0)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  useEffect(() => {
    const updateSections = () => {
      const scope = containerRef?.current ?? document
      const elements = Array.from(scope.querySelectorAll(selector)) as HTMLElement[]
      const next: DocsScrollbarSection[] = []
      for (const element of elements) {
        const titleEl = element.querySelector('h2, h3, [data-section-title]')
        if (!titleEl) continue
        const clone = titleEl.cloneNode(true) as HTMLElement
        const badgeEl = clone.querySelector('[data-slot="badge"]')
        let badge = ''
        if (badgeEl) {
          badge = badgeEl.textContent?.trim() || ''
          badgeEl.remove()
        }
        next.push({
          index: next.length,
          title: clone.textContent?.trim() || '',
          badge,
          element,
        })
      }
      setSections(next)
    }

    updateSections()
    const observer = new MutationObserver(updateSections)
    const observeTarget = containerRef?.current ?? document.body
    observer.observe(observeTarget, { childList: true, subtree: true })
    return () => observer.disconnect()
  }, [containerRef, selector])

  useEffect(() => {
    if (sections.length === 0) return
    const root = containerRef?.current ?? null
    const getScrollTop = () => (root ? root.scrollTop : window.scrollY)

    const handleScroll = () => {
      if (getScrollTop() < 50) setActiveSection(0)
    }
    const scrollTarget: HTMLElement | Window = root ?? window
    scrollTarget.addEventListener('scroll', handleScroll, { passive: true })
    handleScroll()

    const observer = new IntersectionObserver(
      (entries) => {
        const intersecting = entries.filter((entry) => entry.isIntersecting)
        if (intersecting.length === 0) return
        const index = sections.findIndex((section) => section.element === intersecting[0].target)
        if (index !== -1 && getScrollTop() >= 80) setActiveSection(index)
      },
      { threshold: 0, root, rootMargin: '-35% 0px -80% 0px' },
    )
    sections.forEach((section) => observer.observe(section.element))
    return () => {
      observer.disconnect()
      scrollTarget.removeEventListener('scroll', handleScroll)
    }
  }, [sections, containerRef])

  if (!mounted || sections.length === 0) return null

  const node = (
    <ScrollBar
      sections={sections}
      activeSection={activeSection}
      containerRef={containerRef}
      className={className}
      portal={portal}
    />
  )

  if (portal && typeof document !== 'undefined') {
    return createPortal(node, document.body)
  }
  return node
}

function useContainerSize(): [RefCallback<HTMLElement>, { width: number; height: number; left: number; top: number }] {
  const [size, setSize] = useState({ width: 0, height: 0, left: 0, top: 0 })
  const ref = useRef<HTMLElement | null>(null)

  const setRef = useCallback((node: HTMLElement | null) => {
    ref.current = node
    if (!node) return
    const rect = node.getBoundingClientRect()
    setSize({ width: rect.width, height: rect.height, left: rect.left, top: rect.top })
  }, [])

  useEffect(() => {
    const handleResize = () => {
      if (!ref.current) return
      const rect = ref.current.getBoundingClientRect()
      setSize({ width: rect.width, height: rect.height, left: rect.left, top: rect.top })
    }
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return [setRef, size]
}

function ScrollBar({
  sections,
  activeSection,
  containerRef,
  className,
  portal,
}: {
  sections: DocsScrollbarSection[]
  activeSection: number
  containerRef?: RefObject<HTMLElement | null>
  className?: string
  portal: boolean
}) {
  const { scrollYProgress } = useScroll(containerRef ? { container: containerRef } : undefined)
  const [trackRef, containerSize] = useContainerSize()
  const scrollX = useTransform(scrollYProgress, [0, 1], [0, Math.max(containerSize.width - 1.5, 0)])
  const [isDragging, setIsDragging] = useState(false)
  const [hoverX, setHoverX] = useState(0)
  const [isHovering, setIsHovering] = useState(false)
  const barRef = useRef<HTMLDivElement>(null)
  const dragControls = useDragControls()
  const motionX = useMotionValue(0)

  useEffect(() => {
    if (isDragging) return
    const unsubscribe = scrollX.on('change', (value: number) => motionX.set(value))
    return () => unsubscribe()
  }, [isDragging, scrollX, motionX])

  const scrollToProgress = (progress: number) => {
    const clamped = Math.max(0, Math.min(1, progress))
    const root = containerRef?.current
    if (root) {
      root.scrollTo({ top: (root.scrollHeight - root.clientHeight) * clamped, behavior: 'instant' })
      return
    }
    const scrollHeight = document.documentElement.scrollHeight - window.innerHeight
    window.scrollTo({ top: scrollHeight * clamped, behavior: 'instant' })
  }

  const ticks = useMemo(
    () =>
      Array.from({ length: 40 }, (_, i) => (
        <motion.div
          key={i}
          initial={{ opacity: 0.2, filter: 'blur(1px)' }}
          animate={{ opacity: i % 5 === 0 ? 1 : 0.2, filter: 'blur(0px)' }}
          transition={{ duration: 0.2, delay: i % 5 === 0 ? (i / 5) * 0.05 : 0, ease: 'easeOut' }}
          className={cn('w-px bg-foreground', 'h-3.75')}
        />
      )),
    [],
  )

  const section = sections[activeSection] || sections[0]

  return (
    <div
      className={cn(
        'z-50 flex flex-col gap-2 overflow-hidden rounded-[1.25rem] border-4 border-muted bg-muted',
        portal ? 'fixed bottom-5 right-5 hidden md:flex' : 'absolute bottom-3 right-3',
        className,
      )}
    >
      <AnimatePresence mode="popLayout">
        <motion.div
          key={activeSection}
          initial={{ y: '100%', opacity: 0 }}
          animate={{ y: '0%', opacity: 1 }}
          exit={{ y: '100%', opacity: 0 }}
          transition={{ duration: 0.5, bounce: 0, type: 'spring' }}
        >
          {section.title ? (
            <div className="relative flex w-64 max-w-64 items-center rounded-xl bg-background p-3">
              <div className="flex-1 overflow-x-auto whitespace-nowrap">
                <span className="flex items-center gap-2 text-sm font-medium text-foreground">
                  {section.title}
                  {section.badge ? (
                    <span
                      data-slot="badge"
                      className="inline-flex h-5 min-w-5 items-center justify-center rounded-full bg-secondary px-1 text-xs font-medium text-secondary-foreground"
                    >
                      {section.badge}
                    </span>
                  ) : null}
                </span>
              </div>
            </div>
          ) : null}
        </motion.div>
      </AnimatePresence>

      <motion.div className="cursor-grab rounded-xl bg-background px-5 will-change-transform">
        <div ref={trackRef}>
          <div
            ref={barRef}
            className="relative flex h-10 items-center justify-center gap-1.5 overflow-hidden rounded-xl"
            onClick={(event) => {
              if (!barRef.current || isDragging || containerSize.width <= 0) return
              scrollToProgress((event.clientX - containerSize.left) / containerSize.width)
            }}
            onMouseEnter={() => setIsHovering(true)}
            onMouseLeave={() => setIsHovering(false)}
            onMouseMove={(event) => {
              if (isDragging) {
                setHoverX(-20)
                return
              }
              setHoverX(Math.max(0, Math.min(event.clientX - containerSize.left, containerSize.width - 6)))
            }}
          >
            {ticks}
            <AnimatePresence mode="popLayout">
              {isHovering && !isDragging ? (
                <motion.div
                  className="absolute h-6 w-1.5 cursor-grab rounded-full bg-blue-300 opacity-40"
                  style={{ left: hoverX, willChange: 'transform' }}
                  transition={{ type: 'tween', duration: 0 }}
                />
              ) : null}
            </AnimatePresence>
            <motion.div
              layout
              drag="x"
              dragControls={dragControls}
              dragConstraints={barRef}
              dragElastic={0}
              dragMomentum={false}
              onDragStart={() => setIsDragging(true)}
              onDrag={(_, info) => {
                if (containerSize.width <= 0) return
                const x = Math.max(0, Math.min(info.point.x - containerSize.left, containerSize.width))
                motionX.set(x)
                scrollToProgress(x / containerSize.width)
              }}
              onDragEnd={() => setIsDragging(false)}
              className="absolute left-0 h-6 w-1.5 cursor-grab rounded-full bg-blue-300 active:cursor-grabbing"
              style={{ x: motionX }}
            />
          </div>
        </div>
      </motion.div>
    </div>
  )
}
